{"explanation":"A radian measures an angle by arc length. Take a circle's radius, bend it around the edge of the circle, and the angle it covers at the center is exactly 1 radian (about 57.3°). That makes the arc length s = rθ when θ is in radians. A full turn takes 2π ≈ 6.28 radius lengths, so 2π radians = 360°. The animation first wraps a radius around the circle. Then it shows about 6.28 radii going all the way around. At the end, you can drag the yellow dot or use the slider to explore any angle.","manimCode":"const C = [-2.5, -0.2, 0];
const R = 2.2;
const P = (a, r = R) => [C[0] + r * Math.cos(a), C[1] + r * Math.sin(a), 0];

const title = new Text({ text: 'What is a radian?', color: WHITE, fontSize: 40 });
title.moveTo([0, 3.5, 0]);
await scene.play(new Write(title));

const circle = new Circle({ radius: R, color: BLUE });
circle.moveTo(C);
const centerDot = new Dot({ point: C, color: WHITE });
await scene.play(new AnimationGroup([new Create(circle), new FadeIn(centerDot)]));

// Step 1: the radius
const radius = new Line({ start: C, end: P(0), color: RED });
radius.setStrokeWidth(6);
const rLab = new MathTex({ latex: 'r', color: RED });
await rLab.waitForRender();
rLab.moveTo([C[0] + R / 2, C[1] - 0.35, 0]);
await scene.play(new Create(radius));
await scene.play(new FadeIn(rLab));

const t1 = new Text({ text: 'Take one radius...', color: WHITE, fontSize: 28 });
t1.moveTo([3.6, 2.2, 0]);
await scene.play(new FadeIn(t1));

// Step 2: lift a copy, stand it tangent, bend it onto the circle
const piece = new Line({ start: C, end: P(0), color: RED });
piece.setStrokeWidth(6);
scene.add(piece);
const tangent = new Line({ start: P(0), end: [P(0)[0], C[1] + R, 0], color: RED });
tangent.setStrokeWidth(6);
await scene.play(new Transform(piece, tangent));

const t2 = new Text({ text: '...and bend it around the circle', color: WHITE, fontSize: 28 });
t2.moveTo([3.6, 1.6, 0]);
await scene.play(new FadeIn(t2));

const arc1 = new Arc({ radius: R, startAngle: 0, angle: 1, arcCenter: C, color: RED, strokeWidth: 6 });
await scene.play(new Transform(piece, arc1));

// Step 3: show the angle
const radius2 = new Line({ start: C, end: P(1), color: RED });
radius2.setStrokeWidth(6);
await scene.play(new Create(radius2));
const angArc = new Arc({ radius: 0.5, startAngle: 0, angle: 1, arcCenter: C, color: YELLOW, strokeWidth: 4 });
await scene.play(new Create(angArc));
const oneRad = new MathTex({ latex: '1\\,\\text{rad}', color: YELLOW });
await oneRad.waitForRender();
oneRad.scale(0.8);
oneRad.moveTo(P(0.5, 0.95));
await scene.play(new Write(oneRad));

const t3 = new MathTex({ latex: '\\text{arc} = r \\;\\Rightarrow\\; \\theta = 1\\text{ rad} \\approx 57.3^\\circ', color: YELLOW });
await t3.waitForRender();
t3.scale(0.75);
t3.moveTo([3.6, 0.8, 0]);
await scene.play(new Write(t3));
await scene.wait(2);

// Step 4: how many radii fit around?
await scene.play(new AnimationGroup([new FadeOut(t1), new FadeOut(t2), new FadeOut(t3), new FadeOut(oneRad), new FadeOut(angArc), new FadeOut(radius2)]));
const t4 = new Text({ text: 'How many radii fit around?', color: WHITE, fontSize: 28 });
t4.moveTo([3.6, 2.2, 0]);
await scene.play(new FadeIn(t4));

const cols = [ORANGE, YELLOW, GREEN, TEAL, PURPLE];
const extra = [];
for (let k = 1; k <= 5; k++) {
  const a = new Arc({ radius: R, startAngle: k, angle: 1, arcCenter: C, color: cols[k - 1], strokeWidth: 6 });
  const n = new Text({ text: String(k + 1), color: cols[k - 1], fontSize: 24 });
  n.moveTo(P(k + 0.5, R + 0.4));
  extra.push(a, n);
  await scene.play(new AnimationGroup([new Create(a), new FadeIn(n)]));
}
const n1 = new Text({ text: '1', color: RED, fontSize: 24 });
n1.moveTo(P(0.5, R + 0.4));
scene.add(n1);
extra.push(n1);
const rest = new Arc({ radius: R, startAngle: 6, angle: 2 * Math.PI - 6, arcCenter: C, color: WHITE, strokeWidth: 6 });
extra.push(rest);
await scene.play(new Create(rest));

const t5 = new MathTex({ latex: '2\\pi \\approx 6.28 \\text{ rad} = 360^\\circ', color: WHITE });
await t5.waitForRender();
t5.scale(0.85);
t5.moveTo([3.6, 1.3, 0]);
await scene.play(new Write(t5));
await scene.wait(2);

// Step 5: interactive exploration
const fadeList = extra.map(m => new FadeOut(m));
fadeList.push(new FadeOut(piece), new FadeOut(t4), new FadeOut(t5), new FadeOut(radius), new FadeOut(rLab));
await scene.play(new AnimationGroup(fadeList));

const formula = new MathTex({ latex: 's = r\\,\\theta', color: YELLOW });
await formula.waitForRender();
formula.moveTo([3.6, 2.2, 0]);
await scene.play(new Write(formula));

const hint = new Text({ text: 'Drag the yellow dot or use the slider', color: GRAY, fontSize: 20 });
hint.moveTo([3.6, -2.8, 0]);
scene.add(hint);

function sectorVerts(th) {
  const v = [C];
  const n = Math.max(2, Math.ceil(th * 20));
  for (let i = 0; i <= n; i++) v.push(P(th * i / n));
  return v;
}

let theta = 1;
const sector = new Polygon({ vertices: sectorVerts(theta), color: BLUE_C });
sector.setFill(BLUE_E, 0.4);
sector.setStrokeWidth(0);
const r1 = new Polygon({ vertices: [C, P(0)], color: RED });
r1.setStrokeWidth(5); r1.setFillOpacity(0);
const r2 = new Polygon({ vertices: [C, P(theta)], color: RED });
r2.setStrokeWidth(5); r2.setFillOpacity(0);
let hiArc = new Arc({ radius: R, startAngle: 0, angle: theta, arcCenter: C, color: YELLOW, strokeWidth: 7 });
const handle = new Dot({ point: P(theta), color: YELLOW });
handle.scale(1.6);
scene.add(sector, r1, r2, hiArc, handle);

let info = null;
async function makeInfo(th) {
  const deg = (th * 180 / Math.PI).toFixed(1);
  const m = new MathTex({
    latex: '\\theta = ' + th.toFixed(2) + '\\text{ rad} = ' + deg + '^\\circ \\\\ s = ' + th.toFixed(2) + '\\,r',
    color: WHITE
  });
  await m.waitForRender();
  m.scale(0.8);
  m.moveTo([3.6, 0.6, 0]);
  return m;
}
let infoToken = 0;
async function refreshInfo(th) {
  const tok = ++infoToken;
  const m = await makeInfo(th);
  if (tok !== infoToken) return;
  if (info) scene.remove(info);
  info = m;
  scene.add(info);
}

function update(th) {
  theta = Math.max(0.01, Math.min(2 * Math.PI - 0.001, th));
  sector.setVertices(sectorVerts(theta));
  r2.setVertices([C, P(theta)]);
  scene.remove(hiArc);
  hiArc = new Arc({ radius: R, startAngle: 0, angle: theta, arcCenter: C, color: YELLOW, strokeWidth: 7 });
  scene.add(hiArc);
  scene.remove(handle);
  handle.moveTo(P(theta));
  scene.add(handle);
  refreshInfo(theta);
}
update(1);

makeDraggable(handle, scene, {
  onDrag: (mob, pos) => {
    const p = mob.getCenter();
    let a = Math.atan2(p[1] - C[1], p[0] - C[0]);
    if (a < 0) a += 2 * Math.PI;
    update(a);
  }
});
makeHoverable(handle, scene, { hoverScale: 1.3, cursor: 'grab' });

const controls = new Controls(scene, { position: 'bottom-left' });
controls.addSlider({ label: 'Angle θ (rad)', min: 0.05, max: 6.28, value: 1, step: 0.01, onChange: (v) => update(v) });
controls.addButton({ label: '1 radian', onClick: () => update(1) });
controls.addButton({ label: 'π radians (180°)', onClick: () => update(Math.PI) });

await scene.wait(999999);"}

